// ---------------------------------------------------------------------------------------
// Minimal SHA-256 (FIPS 180-4) to compare decoded PCM with the manifest
// ---------------------------------------------------------------------------------------

typedef struct {
    uint32_t h[8];
    uint64_t bytes;
    uint8_t block[64];
    size_t used;
} sha256_t;

static const uint32_t SHA_K[64] = {
    0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u, 0x3956c25bu, 0x59f111f1u,
    0x923f82a4u, 0xab1c5ed5u, 0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
    0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u, 0xe49b69c1u, 0xefbe4786u,
    0x0fc19dc6u, 0x240ca1ccu, 0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
    0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u, 0xc6e00bf3u, 0xd5a79147u,
    0x06ca6351u, 0x14292967u, 0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
    0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u, 0xa2bfe8a1u, 0xa81a664bu,
    0xc24b8b70u, 0xc76c51a3u, 0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
    0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u, 0x391c0cb3u, 0x4ed8aa4au,
    0x5b9cca4fu, 0x682e6ff3u, 0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
    0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u,
};

static uint32_t ror32(uint32_t x, unsigned n)
{
    return (x >> n) | (x << (32u - n));
}

static void sha256_compress(sha256_t *s, const uint8_t *p)
{
    uint32_t w[64];
    for (unsigned i = 0; i < 16; i++) {
        w[i] = ((uint32_t)p[4 * i] << 24) | ((uint32_t)p[4 * i + 1] << 16) |
               ((uint32_t)p[4 * i + 2] << 8) | (uint32_t)p[4 * i + 3];
    }
    for (unsigned i = 16; i < 64; i++) {
        const uint32_t s0 = ror32(w[i - 15], 7) ^ ror32(w[i - 15], 18) ^ (w[i - 15] >> 3);
        const uint32_t s1 = ror32(w[i - 2], 17) ^ ror32(w[i - 2], 19) ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    uint32_t a = s->h[0], b = s->h[1], c = s->h[2], d = s->h[3];
    uint32_t e = s->h[4], f = s->h[5], g = s->h[6], h = s->h[7];
    for (unsigned i = 0; i < 64; i++) {
        const uint32_t t1 = h + (ror32(e, 6) ^ ror32(e, 11) ^ ror32(e, 25)) + ((e & f) ^ (~e & g)) +
                            SHA_K[i] + w[i];
        const uint32_t t2 = (ror32(a, 2) ^ ror32(a, 13) ^ ror32(a, 22)) + ((a & b) ^ (a & c) ^ (b & c));
        h = g;
        g = f;
        f = e;
        e = d + t1;
        d = c;
        c = b;
        b = a;
        a = t1 + t2;
    }
    s->h[0] += a;
    s->h[1] += b;
    s->h[2] += c;
    s->h[3] += d;
    s->h[4] += e;
    s->h[5] += f;
    s->h[6] += g;
    s->h[7] += h;
}

static void sha256_init(sha256_t *s)
{
    static const uint32_t H0[8] = { 0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
                                    0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u };
    memcpy(s->h, H0, sizeof(H0));
    s->bytes = 0;
    s->used = 0;
}

static void sha256_update(sha256_t *s, const void *data, size_t len)
{
    const uint8_t *p = data;
    s->bytes += len;
    while (len > 0) {
        size_t take = 64u - s->used;
        if (take > len) take = len;
        memcpy(s->block + s->used, p, take);
        s->used += take;
        p += take;
        len -= take;
        if (s->used == 64u) {
            sha256_compress(s, s->block);
            s->used = 0;
        }
    }
}

static void sha256_hex(sha256_t *s, char out[65])
{
    const uint64_t bits = s->bytes * 8u;
    const uint8_t pad = 0x80;
    const uint8_t zero = 0;
    sha256_update(s, &pad, 1);
    while (s->used != 56u) sha256_update(s, &zero, 1);
    uint8_t len_be[8];
    for (unsigned i = 0; i < 8; i++) len_be[i] = (uint8_t)(bits >> (56u - 8u * i));
    sha256_update(s, len_be, 8);
    for (unsigned i = 0; i < 8; i++) snprintf(out + 8 * i, 9, "%08x", (unsigned)s->h[i]);
}

static void sha256_of(const void *data, size_t len, char out[65])
{
    sha256_t s;
    sha256_init(&s);
    sha256_update(&s, data, len);
    sha256_hex(&s, out);
}

static void test_sha256_known_answers(void)
{
    char hex[65];
    sha256_of("", 0, hex);
    CHECK(strcmp(hex, "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855") == 0,
          "SHA-256 of the empty string: %s", hex);
    sha256_of("abc", 3, hex);
    CHECK(strcmp(hex, "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad") == 0,
          "SHA-256 of abc: %s", hex);
    const char *two = "abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq";
    sha256_of(two, strlen(two), hex);
    CHECK(strcmp(hex, "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1") == 0,
          "SHA-256 of the two-block message: %s", hex);
}

// ---------------------------------------------------------------------------------------
// Decoder
// ---------------------------------------------------------------------------------------

static void test_header(void)
{
    vocab_adpcm_state_t st;
    const uint8_t ok[VOCAB_ADPCM_HEADER_BYTES] = { 0x34, 0x12, 5, 0 };
    CHECK(vocab_adpcm_init(&st, ok, sizeof(ok)) && st.predictor == 0x1234 && st.step_index == 5,
          "header parsed");
    const uint8_t neg[VOCAB_ADPCM_HEADER_BYTES] = { 0x00, 0x80, 88, 0 };
    CHECK(vocab_adpcm_init(&st, neg, sizeof(neg)) && st.predictor == -32768 && st.step_index == 88,
          "negative predictor and index 88 accepted");
    const uint8_t minus1[VOCAB_ADPCM_HEADER_BYTES] = { 0xFF, 0xFF, 0, 0 };
    CHECK(vocab_adpcm_init(&st, minus1, sizeof(minus1)) && st.predictor == -1, "predictor -1");
    const uint8_t bad[VOCAB_ADPCM_HEADER_BYTES] = { 0x34, 0x12, 89, 0 };
    st.predictor = 77;
    st.step_index = 7;
    CHECK(!vocab_adpcm_init(&st, bad, sizeof(bad)) && st.predictor == 0 && st.step_index == 0,
          "step index > 88 rejected and state reset");
    st.predictor = 77;
    CHECK(!vocab_adpcm_init(&st, ok, 3) && st.predictor == 0, "short header rejected");
    CHECK(!vocab_adpcm_init(&st, NULL, 4) && st.predictor == 0, "NULL clip rejected");
}

static void test_vectors(void)
{
    for (size_t v = 0; v < sizeof(VECTORS) / sizeof(VECTORS[0]); v++) {
        const vector_t *t = &VECTORS[v];
        vocab_adpcm_state_t st = { t->pred0, t->idx0 };
        for (unsigned i = 0; i < t->n; i++) {
            const int16_t got = vocab_adpcm_step(&st, t->codes[i]);
            CHECK(got == t->pred[i] && st.predictor == t->pred[i] && st.step_index == t->idx[i],
                  "%s: step %u: got (%d, %u), reference (%d, %u)", t->name, i, got,
                  st.step_index, t->pred[i], t->idx[i]);
        }
    }
}

static void test_packed_decoding(void)
{
    // The longest vector packed low nibble first; decode it whole, in odd-sized chunks
    // (odd first_code offsets), and from a mid-stream state.
    const vector_t *t = &VECTORS[sizeof(VECTORS) / sizeof(VECTORS[0]) - 1];
    uint8_t packed[64] = { 0 };
    CHECK(t->n <= 2u * sizeof(packed), "vector fits");
    for (unsigned i = 0; i < t->n; i++) {
        packed[i / 2] |= (uint8_t)((t->codes[i] & 15u) << ((i & 1u) ? 4 : 0));
    }
    int16_t out[128];
    vocab_adpcm_state_t st = { t->pred0, t->idx0 };
    CHECK(vocab_adpcm_decode(&st, packed, 0, t->n, out) == t->n, "decode returns n");
    CHECK(memcmp(out, t->pred, t->n * sizeof(int16_t)) == 0, "whole decode matches reference");

    static const size_t chunks[] = { 1, 2, 3, 7, 16, 255 };
    for (size_t c = 0; c < sizeof(chunks) / sizeof(chunks[0]); c++) {
        vocab_adpcm_state_t cs = { t->pred0, t->idx0 };
        memset(out, 0, sizeof(out));
        for (size_t pos = 0; pos < t->n;) {
            const size_t n = (t->n - pos) < chunks[c] ? (t->n - pos) : chunks[c];
            vocab_adpcm_decode(&cs, packed, pos, n, out + pos);
            pos += n;
        }
        CHECK(memcmp(out, t->pred, t->n * sizeof(int16_t)) == 0, "chunk %zu decode matches",
              chunks[c]);
    }
    vocab_adpcm_state_t mid = { t->pred[4], t->idx[4] };
    vocab_adpcm_decode(&mid, packed, 5, 3, out);
    CHECK(out[0] == t->pred[5] && out[1] == t->pred[6] && out[2] == t->pred[7],
          "decode from odd first_code 5");
    CHECK(vocab_adpcm_decode(&mid, packed, 0, 0, out) == 0, "zero samples");
}

