static const uint8_t EMPTY_PACK[24] = {
    0x56, 0x43, 0x4c, 0x50, 0x01, 0x00, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00, 0x18, 0x00, 0x00, 0x00,
    0x8b, 0x18, 0x95, 0xe7, 0x00, 0x00, 0x00, 0x00,
};

// Independent writer used to craft valid and malformed packs (zlib CRC-32, little-endian).
static uint32_t test_crc32(const uint8_t *p, size_t n, uint32_t crc)
{
    for (size_t i = 0; i < n; i++) {
        crc ^= p[i];
        for (int k = 0; k < 8; k++) crc = (crc & 1u) ? (crc >> 1) ^ 0xEDB88320u : crc >> 1;
    }
    return crc;
}

static void put16(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)(v & 0xFFu);
    p[1] = (uint8_t)((v >> 8) & 0xFFu);
}

static void put32(uint8_t *p, uint32_t v)
{
    for (unsigned i = 0; i < 4; i++) p[i] = (uint8_t)((v >> (8u * i)) & 0xFFu);
}

static uint32_t get32(const uint8_t *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

// Recomputes the header CRC after an edit (count read from the header, clamped).
static void fix_crc(uint8_t *blob, size_t size)
{
    uint32_t count = get32(blob + 8);
    size_t index_bytes = (size_t)count * VOCAB_CLIPS_ENTRY_BYTES;
    if (VOCAB_CLIPS_HEADER_BYTES + index_bytes > size) index_bytes = size - VOCAB_CLIPS_HEADER_BYTES;
    uint32_t crc = test_crc32(blob, 16, 0xFFFFFFFFu);
    crc = test_crc32(blob + VOCAB_CLIPS_HEADER_BYTES, index_bytes, crc);
    put32(blob + 16, crc ^ 0xFFFFFFFFu);
}

typedef struct {
    vocab_uid_t uid;
    int16_t predictor;
    uint8_t index;
    uint8_t n_codes;
    uint8_t codes[8];
} test_clip_t;

// Writes a pack of `n` clips into `out` (clips in the given order); returns its size.
static size_t write_pack(const test_clip_t *clips, size_t n, uint8_t *out, size_t cap)
{
    size_t cursor = VOCAB_CLIPS_HEADER_BYTES + n * VOCAB_CLIPS_ENTRY_BYTES;
    memset(out, 0, cap);
    for (size_t i = 0; i < n; i++) {
        cursor = (cursor + 3u) & ~(size_t)3u;
        const size_t bytes = VOCAB_ADPCM_HEADER_BYTES + (clips[i].n_codes + 1u) / 2u;
        uint8_t *e = out + VOCAB_CLIPS_HEADER_BYTES + i * VOCAB_CLIPS_ENTRY_BYTES;
        put16(e, clips[i].uid);
        put32(e + 4, (uint32_t)cursor);
        put32(e + 8, clips[i].n_codes);
        put32(e + 12, (uint32_t)bytes);
        uint8_t *c = out + cursor;
        put16(c, (uint16_t)clips[i].predictor);
        c[2] = clips[i].index;
        for (unsigned k = 0; k < clips[i].n_codes; k++) {
            c[4 + k / 2] |= (uint8_t)((clips[i].codes[k] & 15u) << ((k & 1u) ? 4 : 0));
        }
        cursor += bytes;
    }
    cursor = (cursor + 3u) & ~(size_t)3u;
    memcpy(out, "VCLP", 4);
    put16(out + 4, VOCAB_CLIPS_VERSION);
    put16(out + 6, VOCAB_CLIPS_ENTRY_BYTES);
    put32(out + 8, (uint32_t)n);
    put32(out + 12, (uint32_t)cursor);
    fix_crc(out, cursor);
    return cursor;
}

static const test_clip_t REF_CLIPS[2] = {
    { 7, 16, 5, 3, { 1, 2, 3 } },
    { 300, -2, 0, 4, { 7, 8, 15, 0 } },
};

static void expect_clip(const vocab_clip_t *c, vocab_uid_t uid, uint32_t offset, uint32_t n_bytes,
                        uint32_t n_samples, const char *what)
{
    CHECK(c && c->uid == uid && c->offset == offset && c->n_bytes == n_bytes &&
              c->n_samples == n_samples,
          "%s: clip %u", what, (unsigned)uid);
}

static void decode_check(const uint8_t *clip, const vocab_clip_t *c, const int16_t *expect)
{
    vocab_adpcm_state_t st;
    int16_t pcm[8];
    CHECK(clip && vocab_adpcm_init(&st, clip, c->n_bytes), "uid %u: clip header", (unsigned)c->uid);
    if (!clip || c->n_samples > 8) return;
    vocab_adpcm_decode(&st, clip + VOCAB_ADPCM_HEADER_BYTES, 0, c->n_samples, pcm);
    CHECK(memcmp(pcm, expect, c->n_samples * sizeof(int16_t)) == 0, "uid %u: decoded samples",
          (unsigned)c->uid);
}

static void test_reference_pack(void)
{
    uint8_t built[128];
    const size_t size = write_pack(REF_CLIPS, 2, built, sizeof(built));
    CHECK(size == sizeof(REF_PACK) && memcmp(built, REF_PACK, size) == 0,
          "the test writer reproduces the pinned reference pack");

    vocab_clip_pack_t pack;
    CHECK(vocab_clip_pack_open(&pack, REF_PACK, sizeof(REF_PACK)) == VOCAB_CLIPS_OK, "open");
    CHECK(pack.count == 2 && pack.size == 72 && pack.data == REF_PACK, "pack fields");
    vocab_clip_t c;
    CHECK(vocab_clip_pack_entry(&pack, 0, &c), "entry 0");
    expect_clip(&c, 7, 56, 6, 3, "entry 0");
    CHECK(vocab_clip_pack_bytes(&pack, &c) == REF_PACK + 56, "bytes of entry 0");
    decode_check(vocab_clip_pack_bytes(&pack, &c), &c, REF_PCM_7);
    CHECK(!vocab_clip_pack_entry(&pack, 2, &c), "entry 2 out of range");
    CHECK(vocab_clip_pack_find(&pack, 300, &c), "find 300");
    expect_clip(&c, 300, 64, 6, 4, "find 300");
    decode_check(vocab_clip_pack_bytes(&pack, &c), &c, REF_PCM_300);
    static const vocab_uid_t absent[] = { 0, 1, 6, 8, 299, 301, 0xFFFF };
    for (size_t i = 0; i < sizeof(absent) / sizeof(absent[0]); i++) {
        CHECK(!vocab_clip_pack_find(&pack, absent[i], &c), "uid %u absent", (unsigned)absent[i]);
    }
    const vocab_clip_t outside = { 7, 68, 6, 3 };
    CHECK(vocab_clip_pack_bytes(&pack, &outside) == NULL, "clip outside the blob -> NULL");

    CHECK(vocab_clip_pack_open(&pack, EMPTY_PACK, sizeof(EMPTY_PACK)) == VOCAB_CLIPS_OK &&
              pack.count == 0,
          "canonical empty pack");
    uint8_t empty[64];
    CHECK(write_pack(NULL, 0, empty, sizeof(empty)) == sizeof(EMPTY_PACK) &&
              memcmp(empty, EMPTY_PACK, sizeof(EMPTY_PACK)) == 0,
          "the test writer reproduces the canonical empty pack");
    CHECK(strcmp(vocab_clips_status_name(VOCAB_CLIPS_ERR_CRC), "index checksum mismatch") == 0 &&
              strcmp(vocab_clips_status_name(VOCAB_CLIPS_OK), "ok") == 0,
          "status names");
}

typedef enum { EDIT_HEADER, EDIT_INDEX, EDIT_DATA } edit_area_t;

typedef struct {
    const char *what;
    size_t offset;
    uint32_t value;
    unsigned width;          // 1, 2 or 4 bytes
    edit_area_t area;        // index edits get a recomputed CRC (only the target rule fails)
    vocab_clips_status_t expect;
} edit_t;

static void test_malformed_packs(void)
{
    static const edit_t EDITS[] = {
        { "magic", 0, 'X', 1, EDIT_HEADER, VOCAB_CLIPS_ERR_MAGIC },
        { "version 2", 4, 2, 2, EDIT_INDEX, VOCAB_CLIPS_ERR_VERSION },
        { "entry size 12", 6, 12, 2, EDIT_INDEX, VOCAB_CLIPS_ERR_VERSION },
        { "count above the maximum", 8, VOCAB_CLIPS_MAX + 1u, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_COUNT },
        { "size field", 12, 76, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_SIZE },
        { "checksum", 16, 0x12345678u, 4, EDIT_HEADER, VOCAB_CLIPS_ERR_CRC },
        { "index byte without a new checksum", 28, 0x3C, 1, EDIT_HEADER, VOCAB_CLIPS_ERR_CRC },
        { "header reserved", 20, 1, 4, EDIT_HEADER, VOCAB_CLIPS_ERR_INDEX },
        { "uid 0", 24, 0, 2, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "uids not ascending", 40, 7, 2, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "entry reserved", 26, 1, 2, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "misaligned offset", 28, 58, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "offset inside the index", 28, 52, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "overlapping clips", 44, 60, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "zero samples", 32, 0, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "n_bytes mismatch", 36, 7, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "clip beyond the blob", 44, 68, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "huge sample count", 48, 0xFFFFFFFFu, 4, EDIT_INDEX, VOCAB_CLIPS_ERR_INDEX },
        { "clip step index 89", 58, 89, 1, EDIT_DATA, VOCAB_CLIPS_ERR_CLIP },
        { "clip reserved byte", 67, 1, 1, EDIT_DATA, VOCAB_CLIPS_ERR_CLIP },
    };
    for (size_t i = 0; i < sizeof(EDITS) / sizeof(EDITS[0]); i++) {
        const edit_t *e = &EDITS[i];
        uint8_t blob[sizeof(REF_PACK)];
        memcpy(blob, REF_PACK, sizeof(blob));
        for (unsigned b = 0; b < e->width; b++) blob[e->offset + b] = (uint8_t)(e->value >> (8u * b));
        if (e->area == EDIT_INDEX) fix_crc(blob, sizeof(blob));
        vocab_clip_pack_t pack = { REF_PACK, 1, 1 };
        const vocab_clips_status_t st = vocab_clip_pack_open(&pack, blob, sizeof(blob));
        CHECK(st == e->expect, "%s: status %s, expected %s", e->what, vocab_clips_status_name(st),
              vocab_clips_status_name(e->expect));
        CHECK(pack.data == NULL && pack.count == 0 && pack.size == 0, "%s: pack left empty", e->what);
        CHECK(vocab_clips_install(blob, sizeof(blob)) == e->expect && vocab_clips_count() == 0 &&
                  vocab_clip_find(7) == NULL && vocab_clip_find(300) == NULL,
              "%s: installs as no clips", e->what);
    }
    vocab_clip_pack_t pack;
    CHECK(vocab_clip_pack_open(&pack, NULL, 72) == VOCAB_CLIPS_ERR_ARG, "NULL data");
    CHECK(vocab_clip_pack_open(&pack, REF_PACK, 20) == VOCAB_CLIPS_ERR_SIZE, "shorter than a header");
    CHECK(vocab_clip_pack_open(&pack, REF_PACK, 70) == VOCAB_CLIPS_ERR_SIZE, "not 4-aligned");
    CHECK(vocab_clip_pack_open(&pack, REF_PACK, 68) == VOCAB_CLIPS_ERR_SIZE, "truncated blob");
    uint8_t longer[76];
    memcpy(longer, REF_PACK, sizeof(REF_PACK));
    memset(longer + sizeof(REF_PACK), 0, 4);
    CHECK(vocab_clip_pack_open(&pack, longer, sizeof(longer)) == VOCAB_CLIPS_ERR_SIZE,
          "trailing bytes beyond the size field");
}

// Random corruptions never make the parser read outside the blob: the blob is copied to the
// start of a guard buffer whose tail is poisoned, and every accepted pack must be consistent.
static void test_random_corruption(void)
{
    uint32_t x = 20261024u;
    unsigned accepted = 0;
    for (unsigned round = 0; round < 20000u; round++) {
        uint8_t buf[sizeof(REF_PACK) + 64];
        memset(buf, 0xA5, sizeof(buf));
        memcpy(buf, REF_PACK, sizeof(REF_PACK));
        x = x * 1664525u + 1013904223u;
        const unsigned flips = 1u + (x >> 28) % 4u;
        for (unsigned f = 0; f < flips; f++) {
            x = x * 1664525u + 1013904223u;
            buf[(x >> 8) % sizeof(REF_PACK)] ^= (uint8_t)(1u + (x >> 24) % 255u);
        }
        x = x * 1664525u + 1013904223u;
        if ((x >> 29) == 0) fix_crc(buf, sizeof(REF_PACK));  // also reach the index rules
        x = x * 1664525u + 1013904223u;
        const size_t size = (x >> 30) == 0 ? (x >> 8) % sizeof(REF_PACK) : sizeof(REF_PACK);
        vocab_clip_pack_t pack;
        if (vocab_clip_pack_open(&pack, buf, size) != VOCAB_CLIPS_OK) {
            CHECK(pack.count == 0 && pack.data == NULL, "round %u: rejected pack is empty", round);
            continue;
        }
        accepted++;
        for (size_t i = 0; i < pack.count; i++) {
            vocab_clip_t c;
            CHECK(vocab_clip_pack_entry(&pack, i, &c) && (uint64_t)c.offset + c.n_bytes <= size,
                  "round %u: accepted entry inside the blob", round);
        }
    }
    CHECK(accepted > 0, "some corruptions keep a valid pack (padding bytes, %u)", accepted);
}

static void test_installed_pack(void)
{
    CHECK(vocab_clips_install(REF_PACK, sizeof(REF_PACK)) == VOCAB_CLIPS_OK, "install");
    CHECK(vocab_clips_count() == 2 && vocab_clips_blob_bytes() == 72, "installed count/size");
    const vocab_clip_t *a = vocab_clip_at(0);
    const vocab_clip_t *b = vocab_clip_at(1);
    expect_clip(a, 7, 56, 6, 3, "at(0)");
    expect_clip(b, 300, 64, 6, 4, "at(1)");
    CHECK(vocab_clip_at(2) == NULL, "at(2) -> NULL");
    CHECK(vocab_clip_find(7) == a && vocab_clip_find(300) == b, "find returns the table entries");
    CHECK(vocab_clip_find(0) == NULL && vocab_clip_find(8) == NULL && vocab_clip_find(0xFFFF) == NULL,
          "unknown uids -> NULL");
    CHECK(vocab_clip_bytes(a) == REF_PACK + 56 && vocab_clip_bytes(b) == REF_PACK + 64, "clip bytes");
    CHECK(vocab_clip_bytes(NULL) == NULL, "bytes(NULL) -> NULL");
    decode_check(vocab_clip_bytes(b), b, REF_PCM_300);
    CHECK(vocab_clips_install(NULL, 0) == VOCAB_CLIPS_ERR_ARG && vocab_clips_count() == 0 &&
              vocab_clips_blob_bytes() == 0 && vocab_clip_find(7) == NULL && vocab_clip_at(0) == NULL,
          "install(NULL) -> no clips");
}

// ---------------------------------------------------------------------------------------
// Committed empty fallback and the local pack (files)
// ---------------------------------------------------------------------------------------

static uint8_t *read_file(const char *path, size_t *size)
{
    *size = 0;
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    uint8_t *data = NULL;
    if (fseek(f, 0, SEEK_END) == 0) {
        const long len = ftell(f);
        if (len >= 0 && fseek(f, 0, SEEK_SET) == 0) {
            data = malloc((size_t)len + 1u);
            if (data && fread(data, 1, (size_t)len, f) == (size_t)len) {
                data[len] = 0;
                *size = (size_t)len;
            } else {
                free(data);
                data = NULL;
            }
        }
    }
    fclose(f);
    return data;
}

static const char *env_or(const char *name, const char *fallback)
{
    const char *v = getenv(name);
    return (v && v[0]) ? v : fallback;
}

static void test_empty_fallback(void)
{
    const char *path = env_or("VOCAB_CLIPS_EMPTY", DEFAULT_EMPTY_PACK);
    size_t size = 0;
    uint8_t *data = read_file(path, &size);
    CHECK(data != NULL, "read the committed empty pack %s (run from the repository root)", path);
    if (!data) return;
    CHECK(size == sizeof(EMPTY_PACK) && memcmp(data, EMPTY_PACK, size) == 0,
          "%s is the canonical empty pack", path);
    CHECK(vocab_clips_install(data, size) == VOCAB_CLIPS_OK && vocab_clips_count() == 0,
          "the empty pack installs as no clips");
    const vocab_bank_t *bank = vocab_bank_builtin();
    for (vocab_index_t i = 0; i < bank->count; i++) {
        CHECK(vocab_clip_find(bank->entries[i].uid) == NULL, "CI build: uid %u has no clip",
              (unsigned)bank->entries[i].uid);
    }
    vocab_clips_install(NULL, 0);
    free(data);
}

typedef struct {
    unsigned uid, offset, bytes, samples;
    char pcm_sha256[65];
} manifest_row_t;

static size_t parse_manifest(char *text, manifest_row_t *rows, size_t cap)
{
    size_t n = 0;
    bool header_seen = false;
    for (char *line = strtok(text, "\r\n"); line; line = strtok(NULL, "\r\n")) {
        if (line[0] == '#' || line[0] == '\0') continue;
        if (!header_seen) {
            static const char columns[] = "uid,offset,bytes,samples,duration_ms,pcm_sha256,";
            CHECK(strncmp(line, columns, sizeof(columns) - 1u) == 0,
                  "manifest column order: %.60s", line);
            header_seen = true;
            continue;
        }
        manifest_row_t r;
        unsigned duration;
        if (n < cap && sscanf(line, "%u,%u,%u,%u,%u,%64[0-9a-f],", &r.uid, &r.offset, &r.bytes,
                              &r.samples, &duration, r.pcm_sha256) == 6) {
            rows[n++] = r;
        } else {
            CHECK(false, "malformed manifest row: %.60s", line);
        }
    }
    return n;
}

static void check_local_layout(void)
{
    const size_t count = vocab_clips_count();
    CHECK(count > 0, "the local pack has clips");
    for (size_t i = 0; i < count; i++) {
        const vocab_clip_t *c = vocab_clip_at(i);
        if (i > 0) CHECK(vocab_clip_at(i - 1)->uid < c->uid, "uids sorted and unique at %zu", i);
        CHECK(c->offset % 4u == 0, "uid %u: offset aligned", (unsigned)c->uid);
        CHECK(c->n_samples > 0 && c->n_bytes == VOCAB_ADPCM_HEADER_BYTES + (c->n_samples + 1u) / 2u,
              "uid %u: n_bytes matches n_samples", (unsigned)c->uid);
        CHECK((uint64_t)c->offset + c->n_bytes <= vocab_clips_blob_bytes(), "uid %u: inside the blob",
              (unsigned)c->uid);
        if (i > 0) {
            const vocab_clip_t *p = vocab_clip_at(i - 1);
            CHECK(p->offset + p->n_bytes <= c->offset, "uid %u: no overlap", (unsigned)c->uid);
        }
        CHECK(vocab_clip_find(c->uid) == c, "uid %u: find returns its entry", (unsigned)c->uid);
    }
    CHECK(vocab_clips_blob_bytes() <= VOCAB_CLIP_BLOB_MAX_BYTES, "pack within the 600 KB budget");

    const vocab_bank_t *bank = vocab_bank_builtin();
    for (vocab_index_t i = 0; i < bank->count; i++) {
        const vocab_entry_t *e = vocab_bank_at(bank, i);
        const vocab_clip_t *c = vocab_clip_find(e->uid);
        CHECK(c && c->uid == e->uid, "bank uid %u (%s) resolves", (unsigned)e->uid, e->text);
        if (c) {
            const uint32_t limit_ms = vocab_entry_kind(e) == VOCAB_KIND_PHRASE
                                          ? VOCAB_CLIP_MAX_PHRASE_MS : VOCAB_CLIP_MAX_WORD_MS;
            CHECK(c->n_samples <= limit_ms * (VOCAB_AUDIO_RATE_HZ / 1000u), "uid %u: duration limit",
                  (unsigned)e->uid);
        }
    }
    CHECK(count == bank->count, "one clip per bank entry (%zu clips, %u entries)", count,
          (unsigned)bank->count);
    static const vocab_uid_t unknown[] = { 0, 1, 100, 105, 200, 999, 1004, 4242, 0xFFFF };
    for (size_t i = 0; i < sizeof(unknown) / sizeof(unknown[0]); i++) {
        vocab_index_t idx;
        if (!vocab_bank_find(bank, unknown[i], &idx)) {
            CHECK(vocab_clip_find(unknown[i]) == NULL, "unknown uid %u -> NULL", (unsigned)unknown[i]);
        }
    }
}

static void check_local_manifest(const char *manifest_path)
{
    size_t text_size = 0;
    char *text = (char *)read_file(manifest_path, &text_size);
    CHECK(text != NULL, "read %s (the local pack needs its manifest)", manifest_path);
    if (!text) return;
    static manifest_row_t rows[512];
    const size_t n_rows = parse_manifest(text, rows, sizeof(rows) / sizeof(rows[0]));
    CHECK(n_rows == vocab_clips_count(), "manifest rows %zu == clips %zu", n_rows, vocab_clips_count());

    static int16_t pcm[VOCAB_AUDIO_CHUNK_SAMPLES];
    for (size_t i = 0; i < vocab_clips_count(); i++) {
        const vocab_clip_t *c = vocab_clip_at(i);
        const manifest_row_t *r = NULL;
        for (size_t k = 0; k < n_rows; k++) {
            if (rows[k].uid == c->uid) r = &rows[k];
        }
        CHECK(r != NULL, "uid %u: manifest row", (unsigned)c->uid);
        if (!r) continue;
        CHECK(r->offset == c->offset && r->bytes == c->n_bytes && r->samples == c->n_samples,
              "uid %u: manifest offset/bytes/samples match the pack index", (unsigned)c->uid);

        // Decode exactly as the audio worker does: header, then 256-sample chunks.
        const uint8_t *clip = vocab_clip_bytes(c);
        vocab_adpcm_state_t st;
        CHECK(clip && vocab_adpcm_init(&st, clip, c->n_bytes), "uid %u: valid header", (unsigned)c->uid);
        if (!clip) continue;
        sha256_t sha;
        sha256_init(&sha);
        int peak = 0;
        for (uint32_t pos = 0; pos < c->n_samples;) {
            const uint32_t left = c->n_samples - pos;
            const size_t n = left < VOCAB_AUDIO_CHUNK_SAMPLES ? left : VOCAB_AUDIO_CHUNK_SAMPLES;
            vocab_adpcm_decode(&st, clip + VOCAB_ADPCM_HEADER_BYTES, pos, n, pcm);
            for (size_t k = 0; k < n; k++) {
                const uint8_t le[2] = { (uint8_t)((uint16_t)pcm[k] & 0xFFu),
                                        (uint8_t)((uint16_t)pcm[k] >> 8) };
                sha256_update(&sha, le, 2);
                const int a = pcm[k] < 0 ? -pcm[k] : pcm[k];
                if (a > peak) peak = a;
            }
            pos += (uint32_t)n;
        }
        char hex[65];
        sha256_hex(&sha, hex);
        CHECK(strcmp(hex, r->pcm_sha256) == 0,
              "uid %u: C-decoded PCM SHA-256 %s != reference %s", (unsigned)c->uid, hex, r->pcm_sha256);
        CHECK(peak <= PEAK_LIMIT, "uid %u: decoded peak %d <= -1 dBFS", (unsigned)c->uid, peak);
    }
    free(text);
}

static void test_local_pack(void)
{
    const char *dir = env_or("VOCAB_CLIPS_DIR", DEFAULT_CLIPS_DIR);
    char blob_path[512];
    char manifest_path[512];
    snprintf(blob_path, sizeof(blob_path), "%s/%s", dir, LOCAL_PACK_NAME);
    snprintf(manifest_path, sizeof(manifest_path), "%s/%s", dir, LOCAL_MANIFEST);
    size_t size = 0;
    uint8_t *blob = read_file(blob_path, &size);
    if (!blob) {
        printf("test_vocab_adpcm: no local clip pack at %s: real-clip checks skipped "
               "(CI and public builds have no word audio)\n", blob_path);
        return;
    }
    const vocab_clips_status_t st = vocab_clips_install(blob, size);
    CHECK(st == VOCAB_CLIPS_OK, "the local pack %s is valid (%s)", blob_path, vocab_clips_status_name(st));
    if (st == VOCAB_CLIPS_OK) {
        check_local_layout();
        check_local_manifest(manifest_path);
        printf("test_vocab_adpcm: local clip pack %s checked (%zu clips)\n", blob_path,
               vocab_clips_count());
    }
    vocab_clips_install(NULL, 0);
    free(blob);
}

int main(void)
{
    test_sha256_known_answers();
    test_header();
    test_vectors();
    test_packed_decoding();
    test_reference_pack();
    test_malformed_packs();
    test_random_corruption();
    test_installed_pack();
    test_empty_fallback();
    test_local_pack();
    return vocab_test_report("vocab ADPCM and clip pack tests");
}
